    const state = typeof step === 'number' ? [
        { currentDirection: 'Right', distanceR: 1.7 },
        { currentDirection: 'Left', distanceR: 1.7 },
        { currentDirection: 'Right', distanceR: 3.8 }
    ][step] : step.state;

    if (!state) return;

    if (state.currentDirection && state.currentDirection !== currentDir) {
        if (state.currentDirection === 'Right') btnRight.click();
        else btnLeft.click();
