let currentDir = 'Right';
const btnRight = document.getElementById('btnRight');
const btnLeft = document.getElementById('btnLeft');

function updateDirection() {
    if (currentDir === 'Right') {
        arrowI.rotation.y = 0;
        bArrowGroups.forEach(g => g.rotation.y = 0);
        handContainer.rotation.y = 0;
    } else {
        arrowI.rotation.y = Math.PI;
        bArrowGroups.forEach(g => g.rotation.y = Math.PI);
        handContainer.rotation.y = Math.PI;
    }
}

btnRight.addEventListener('click', () => {
    if (currentDir === 'Right') return;
    currentDir = 'Right';
    btnRight.classList.add('active');
    btnLeft.classList.remove('active');
    updateDirection();
});

btnLeft.addEventListener('click', () => {
    if (currentDir === 'Left') return;
    currentDir = 'Left';
    btnLeft.classList.add('active');
    btnRight.classList.remove('active');
    updateDirection();
});

window.goToStep = function(step) {
    const state = typeof step === 'number' ? [
        { currentDirection: 'Right' },
        { currentDirection: 'Left' }
    ][step] : step.state;

    if (!state) return;

    if (state.currentDirection && state.currentDirection !== currentDir) {
        if (state.currentDirection === 'Right') btnRight.click();
        else btnLeft.click();
    }
};

